import{_ as s,o as n,c as e,S as p}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse('{"title":"macOS下编译C++文件","description":"","frontmatter":{"title":"macOS下编译C++文件","date":"2023-10-09 12:10","comments":true,"archives":2023,"tags":["C++"]},"headers":[],"relativePath":"posts/2023-10-09-macos-build-cpp/index.md","filePath":"posts/2023/2023-10-09-macos-build-cpp.md"}'),l={name:"posts/2023-10-09-macos-build-cpp/index.md"};function i(r,a,c,o,t,b){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>WebAssembly 是一种新的编译目标，可以将 C/C++ 等语言编译成 WebAssembly，然后在浏览器中运行。我最近在研究如何把<a href="https://github.com/mchehab/zbar" target="_blank" rel="noreferrer">zbar</a>编译成 WebAssembly，然后在浏览器中使用。第一步就是想把官方的例子编译成二进制测试下代码，但是在 MacOS 下编译的时候遇到了一些问题，这里记录下。</p><h2 id="官方例子" tabindex="-1">官方例子 <a class="header-anchor" href="#官方例子" aria-label="Permalink to &quot;官方例子&quot;">​</a></h2><p><a href="https://github.com/mchehab/zbar/blob/master/examples/scan_image.cpp" target="_blank" rel="noreferrer">scan_image.cpp</a></p><p>官方提供了一个例子，可以用来测试二维码识别功能，这个例子有两个依赖 Magick++.h 和 zbar.h，这两个库都可以通过 brew 安装。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">brew</span><span style="color:#032F62;"> install</span><span style="color:#032F62;"> imagemagick</span></span>
<span class="line"><span style="color:#6F42C1;">brew</span><span style="color:#032F62;"> install</span><span style="color:#032F62;"> zbar</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>因为从源码编译对我来说实在是太复杂了，所以我就选择了直接安装相关依赖。</p><h2 id="编译" tabindex="-1">编译 <a class="header-anchor" href="#编译" aria-label="Permalink to &quot;编译&quot;">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">g++</span><span style="color:#005CC5;"> -o</span><span style="color:#032F62;"> scan_image</span><span style="color:#032F62;"> scan_image.cpp</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>执行上面的命令，会报错：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>scan_image.cpp:1:10: fatal error: &#39;Magick++.h&#39; file not found</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这是因为 Magick++.h 的头文件在 <code>/opt/homebrew/include/ImageMagick-7/Magick++.h</code>，但是 g++ 默认只会在 <code>/opt/homebrew/include</code> 目录下查找头文件，所以我们需要指定头文件的路径。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">g++</span><span style="color:#005CC5;"> -o</span><span style="color:#032F62;"> scan_image</span><span style="color:#032F62;"> scan_image.cpp</span><span style="color:#005CC5;"> -I/opt/homebrew/include/ImageMagick-7</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>执行上面的命令还是会有报错：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>/opt/homebrew/include/ImageMagick-7/MagickCore/magick-config.h:63:3: warning: &quot;you should set MAGICKCORE_QUANTUM_DEPTH to sensible default set it to configure time default&quot; [-W#warnings]</span></span>
<span class="line"><span># warning &quot;you should set MAGICKCORE_QUANTUM_DEPTH to sensible default set it to configure time default&quot;</span></span>
<span class="line"><span>  ^</span></span>
<span class="line"><span>/opt/homebrew/include/ImageMagick-7/MagickCore/magick-config.h:64:3: warning: &quot;this is an obsolete behavior please fix your makefile&quot; [-W#warnings]</span></span>
<span class="line"><span># warning &quot;this is an obsolete behavior please fix your makefile&quot;</span></span>
<span class="line"><span>  ^</span></span>
<span class="line"><span>/opt/homebrew/include/ImageMagick-7/MagickCore/magick-config.h:86:3: error: &quot;you should set MAGICKCORE_HDRI_ENABLE&quot;</span></span>
<span class="line"><span># error &quot;you should set MAGICKCORE_HDRI_ENABLE&quot;</span></span>
<span class="line"><span>  ^</span></span>
<span class="line"><span>/opt/homebrew/include/ImageMagick-7/MagickCore/magick-config.h:121:3: error: &quot;you should set MAGICKCORE_HDRI_ENABLE&quot;</span></span>
<span class="line"><span># error &quot;you should set MAGICKCORE_HDRI_ENABLE&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>我们需要设置两个 ImageMagick 需要的编译变量：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">g++</span><span style="color:#005CC5;"> -o</span><span style="color:#032F62;"> scan_image</span><span style="color:#032F62;"> scan_image.cpp</span><span style="color:#005CC5;"> -I/opt/homebrew/include/ImageMagick-7</span><span style="color:#005CC5;"> -DMAGICKCORE_QUANTUM_DEPTH=16</span><span style="color:#005CC5;"> -DMAGICKCORE_HDRI_ENABLE=0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>设置了这两个变量之后，还是会报错：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>Undefined symbols for architecture arm64:</span></span>
<span class="line"><span>  &quot;Magick::Blob::Blob()&quot;, referenced from:</span></span>
<span class="line"><span>      _main in scan_image-727bdc.o</span></span>
<span class="line"><span>  &quot;_zbar_get_symbol_name&quot;, referenced from:</span></span>
<span class="line"><span>      zbar::Symbol::get_type_name() const in scan_image-727bdc.o</span></span>
<span class="line"><span>ld: symbol(s) not found for architecture arm64</span></span>
<span class="line"><span>clang: error: linker command failed with exit code 1 (use -v to see invocation)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>这是因为我们只引用了头文件，却没有引用相关库的实现。我们需要指定 ImageMagick 的库文件路径，这里我使用的是 brew 安装的 ImageMagick，所以库文件在 <code>/opt/homebrew/lib/ImageMagick</code> 目录下。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">g++</span><span style="color:#005CC5;"> -o</span><span style="color:#032F62;"> scan_image</span><span style="color:#032F62;"> scan_image.cpp</span><span style="color:#005CC5;"> -I/opt/homebrew/include/ImageMagick-7</span><span style="color:#005CC5;"> -L/opt/homebrew/lib/ImageMagick</span><span style="color:#005CC5;"> -DMAGICKCORE_QUANTUM_DEPTH=16</span><span style="color:#005CC5;"> -DMAGICKCORE_HDRI_ENABLE=0</span><span style="color:#005CC5;"> -lMagick++-7.Q16HDRI</span><span style="color:#005CC5;"> -lzbar</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>同时我们需要使用 -l 参数来指定需要链接的库，这里需要链接 Magick++-7.Q16HDRI 和 zbar。</p><h2 id="cmake" tabindex="-1">CMake <a class="header-anchor" href="#cmake" aria-label="Permalink to &quot;CMake&quot;">​</a></h2><p>上面的编译命令比较长，而且如果我们需要编译多个文件的时候，就需要写很多次，所以我们可以使用 CMake 来简化编译过程。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>cmake_minimum_required(VERSION 3.10)</span></span>
<span class="line"><span>project(ScanImage)</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>set(CMAKE_CXX_STANDARD 11)</span></span>
<span class="line"><span>set(CMAKE_CXX_FLAGS &quot;-DMAGICKCORE_HDRI_ENABLE=1 -DMAGICKCORE_QUANTUM_DEPTH=16&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>include_directories(/opt/homebrew/include/ImageMagick-7)</span></span>
<span class="line"><span>link_directories(/opt/homebrew/lib/ImageMagick)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>add_executable(ScanImage scan_image.cpp)</span></span>
<span class="line"><span>target_link_libraries(ScanImage zbar Magick++-7.Q16HDRI)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>C++ 的编译报错总是让人摸不着头脑，这里我只是简单的记录了下我遇到的问题和解决方案，希望能帮助到大家。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://stackoverflow.com/questions/17887265/how-to-include-third-party-libraries" target="_blank" rel="noreferrer">how to #include third party libraries</a></p><p><a href="https://github.com/undecaf/zbar-wasm" target="_blank" rel="noreferrer">zbar-wasm</a></p>`,29)])])}const m=s(l,[["render",i]]);export{u as __pageData,m as default};
